// Arma UN mensaje de Telegram (formato HTML) con todos los avisos graves pendientes de Telegram.
// De noche (fuera de hora_inicio..hora_fin, hora de Monterrey) no manda nada: los avisos se quedan
// pendientes y salen juntos, como resumen, en la primera vuelta despues de hora_inicio.
const CANAL = 'telegram';
const MAX_LINEAS = 15; // por seccion; Telegram corta en 4096 caracteres
const cfg = $('Configuracion').first().json;
const pendientes = ($input.first().json.pendientes ?? []).filter((p) => p.canal === CANAL);
const hora = Number(new Intl.DateTimeFormat('en-US', { timeZone: 'America/Monterrey', hour: 'numeric', hourCycle: 'h23' }).format(new Date()));
if (pendientes.length === 0 || hora < cfg.hora_inicio || hora >= cfg.hora_fin) return [];

const esc = (t) => String(t ?? '').replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
const NOMBRE = { temperatura: 'Temperatura fuera de rango', humedad: 'Humedad fuera de rango', puerta_abierta: 'Puerta abierta de más', nodo_sin_reporte: 'Nodo sin reportar', sensor_falla: 'Falla de sensor', golpe: 'Golpe en el anaquel', movimiento_fuera_de_horario: 'Movimiento fuera de horario', luz: 'Luz fuera de horario' };
const NODO = { dht: 'Temperatura y humedad', luz: 'Luz', pir: 'Presencia', puerta: 'Puerta', acel: 'Golpes' };
const UNIDAD = { temperatura: ' °C', humedad: ' % HR' };
const fmt = new Intl.DateTimeFormat('es-MX', { timeZone: 'America/Monterrey', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });

const linea = (p) => {
  const valor = UNIDAD[p.tipo] && p.valor !== null && p.valor !== undefined ? ' (' + p.valor + UNIDAD[p.tipo] + ')' : '';
  return (p.ts_fin ? '✅ ' : '🔴 ') + '<b>' + esc((NOMBRE[p.tipo] ?? p.tipo) + valor) + '</b>\n'
    + '      ' + esc(NODO[p.id_nodo] ?? p.id_nodo) + ' · desde ' + esc(fmt.format(new Date(p.ts_inicio)));
};
const seccion = (titulo, lista) => {
  if (lista.length === 0) return '';
  const extra = lista.length > MAX_LINEAS ? '\n<i>…y ' + (lista.length - MAX_LINEAS) + ' más</i>' : '';
  return '\n\n<b>' + titulo + ' (' + lista.length + ')</b>\n' + lista.slice(0, MAX_LINEAS).map(linea).join('\n') + extra;
};
const activas = pendientes.filter((p) => !p.ts_fin);
const resueltas = pendientes.filter((p) => p.ts_fin);

let texto = (activas.length ? '🚨' : 'ℹ️') + ' <b>ARGOS · ' + (pendientes.length === 1 ? '1 alerta grave' : pendientes.length + ' alertas graves') + '</b>\n'
  + 'Cuarto de incubación in vitro'
  + seccion('Siguen activas', activas)
  + seccion('Ya se resolvieron', resueltas);

const url = String(cfg.dashboard_url ?? '').trim();
const conLink = /^https:\/\/\S+$/.test(url);
if (conLink) texto += '\n\n👉 <a href="' + esc(url) + '">Abrir el dashboard</a>';

return [{ json: { canal: CANAL, ids: pendientes.map((p) => p.id_alerta), texto, url: conLink ? url : '' } }];
